mapper.select:
select fie.id fieldId, fie.field_name fieldName, fie.field_code fieldCode, fie.field_type fieldType, ifnull(rf.sort, fie.sort) sort, ifnull(rf.is_default, 0) isDefault, ifnull(rf.is_basic, 0) isBasic, ifnull(rf.is_visit_basic, 0) isVisitBasic, rf.is_dict isDict, rf.dict_type dictType, ta.id tableId, ta.table_code tableCode, ta.table_name tableName, ta.is_loop isLoop, ta.primary_code primaryCode, ta.slave_type slaveType, ta.main_table_code mainTableCode from cbdses_table ta inner join cbdses_table_field fie on ta.id = fie.table_id left join cbdses_result_field rf on rf.field_code = fie.field_code and rf.table_code = ta.table_code where ta.is_deleted = 0 and fie.is_deleted = 0 and fie.id in
#{item}
order by rf.sort
